            cmd_configure(args)
        elif args.command == "run":
            cmd_run(args)
        elif args.command == "status":
            cmd_status(args)
        elif args.command == "approve":
            cmd_approve(args)
        elif args.command == "doctor":
            cmd_doctor(args)
        elif args.command == "backtest":
            cmd_backtest(args)
        else:
            parser.print_help()
    finally:
        flush_telemetry()


if __name__ == "__main__":
    main()

