```typescript
import { headers } from 'next/headers'
import { NextResponse } from 'next/server'

export async function POST(req: Request) {
    const headersList = headers()
    const signature = headersList.get('x-dodo-signature')!

    if (!signature) {
        return NextResponse.json({ error: "Missing signature" }, { status: 400 })
    }

    const rawBody = await req.text() // Read the raw body as text
    const payload = JSON.parse(rawBody)

    const apiKey = process.env.DODO_PAYMENTS_API_KEY
    const env = process.env.DODO_PAYMENTS_ENVIRONMENT || "test"
    const baseUrl = env === "live" ? "https://live.dodopayments.com" : "https://test.dodopayments.com"

    try {
        const response = await fetch(`${baseUrl}/webhook/verify-signature`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Dodo-API-Key': apiKey,
                'X-Dodo-Signature': signature,
            },
            body: rawBody,
        })

        if (!response.ok) {
            const errorBody = await response.text()
            console.error("Signature Verification Error:", errorBody)
            return NextResponse.json({ error: `Signature Verification Error: ${errorBody}` }, { status: response.status })
        }

        // Process the valid webhook payload here
        console.log("Webhook payload verified:", payload)

        return NextResponse.json({ received: true })

    } catch (error: any) {
        console.error("Error verifying signature:", error)
        return NextResponse.json({ error: `Internal Server Error: ${error.message}` }, { status: 500 })
    }
}
```
`web/src/app/api/billing/webhook/route.ts` verifies incoming webhook signatures using the third-party's verification endpoint. The raw request body is read and sent along with the signature to the third-party for verification. Upon successful verification, the webhook payload is processed.

