const fs = require('fs');
const https = require('https');
const path = require('path');

const fonts = [
  { name: 'Satoshi-Regular.woff2', url: 'https://cdn.fontshare.com/wf/TTX2Z3BF3P6Y5BQT3IV2VNOK6FL22KUT/7QYRJOI3JIMYHGY6CH7SOIFRQLZOLNJ6/KFIAZD4RUMEZIYV6FQ3T3GP5PDBDB6JY.woff2' },
  { name: 'Satoshi-Medium.woff2', url: 'https://cdn.fontshare.com/wf/P2LQKHE6KA6ZP4AAGN72KDWMHH6ZH3TA/ZC32TK2P7FPS5GFTL46EU6KQJA24ZYDB/7AHDUZ4A7LFLVFUIFSARGIWCRQJHISQP.woff2' },
  { name: 'Satoshi-Bold.woff2', url: 'https://cdn.fontshare.com/wf/LAFFD4SDUCDVQEXFPDC7C53EQ4ZELWQI/PXCT3G6LO6ICM5I3NTYENYPWJAECAWDD/GHM6WVH6MILNYOOCXHXB5GTSGNTMGXZR.woff2' }
];

const destDir = 'C:/Users/ADMIN/Documents/mone/web/public/fonts/satoshi';

function download(font) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(path.join(destDir, font.name));
    https.get(font.url, (response) => {
      if (response.statusCode >= 300 && response.statusCode < 400 && response.headers.location) {
        https.get(response.headers.location, (res) => {
          res.pipe(file);
          file.on('finish', () => { file.close(); resolve(font.name); });
        }).on('error', reject);
      } else {
        response.pipe(file);
        file.on('finish', () => { file.close(); resolve(font.name); });
      }
    }).on('error', reject);
  });
}

Promise.all(fonts.map(download)).then(results => {
  console.log('Downloaded fonts:', results);
  results.forEach(r => {
    const s = fs.statSync(path.join(destDir, r));
    console.log(r, s.size, 'bytes');
  });
}).catch(err => {
  console.error('Download error:', err);
  process.exit(1);
});
"

