import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** @type {import('tailwindcss').Config} */
module.exports = {
  darkMode: "class",
  content: [
    "./src/pages/**/*.{js,ts,jsx,tsx,mdx}",
    "./src/components/**/*.{js,ts,jsx,tsx,mdx}",
    "./src/app/**/*.{js,ts,jsx,tsx,mdx}",
    "./src/lib/**/*.{js,ts,jsx,tsx,mdx}",
  ],
  theme: {
    extend: {
      colors: {
        background: "var(--geist-background)",
        foreground: "var(--geist-foreground)",
        "ds-gray": {
          100: "var(--ds-gray-100)",
          200: "var(--ds-gray-200)",
          400: "var(--ds-gray-400)",
          500: "var(--ds-gray-500)",
          900: "var(--ds-gray-900)",
          1000: "var(--ds-gray-1000)",
        },
        "ds-blue": {
          700: "var(--ds-blue-700)",
          900: "var(--ds-blue-900)",
        },
        geist: {
          success: "var(--geist-success)",
          error: "var(--geist-error)",
          warning: "var(--geist-warning)",
          selection: "var(--geist-selection)",
        },
      },
      fontFamily: {
        outfit: ["var(--font-outfit)", "-apple-system", "sans-serif"],
        satoshi: ["var(--font-satoshi)", "-apple-system", "sans-serif"],
        sans: ["var(--font-satoshi)", "-apple-system", "sans-serif"],
        mono: [
          "ui-monospace",
          "SFMono-Regular",
          "Menlo",
          "Monaco",
          "Consolas",
          "monospace",
        ],
      },
      borderRadius: {
        DEFAULT: "6px",
      },
    },
  },
  plugins: [],
};

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Vercel Geist Design System Color Tokens */
:root {
  /* Light Mode */
  --geist-background: #ffffff;
  --geist-foreground: #000000;

  /* Gray Scale */
  --ds-gray-100: hsla(0, 0%, 98%, 1);  /* #fafafa - Subtle surface offset */
  --ds-gray-200: hsla(0, 0%, 95%, 1);  /* #f2f2f2 */
  --ds-gray-400: hsla(0, 0%, 90%, 1);  /* #eaeaea - Crisp 1px border */
  --ds-gray-500: hsla(0, 0%, 75%, 1);  /* #bfbfbf */
  --ds-gray-900: hsla(0, 0%, 40%, 1);  /* #666666 - Secondary text */
  --ds-gray-1000: hsla(0, 0%, 9%, 1);  /* #171717 - Primary high contrast */

  /* Primary Accent & Interactive */
  --ds-blue-700: hsla(212, 100%, 48%, 1); /* #0070f3 - Primary action */
  --ds-blue-900: hsla(210, 100%, 40%, 1); /* Hover state */

  /* Semantic UI */
  --geist-success: #0070f3;
  --geist-error: #ee0000;
  --geist-warning: #f5a623;

  /* Focus & Selection */
  --ds-focus-color: var(--ds-blue-700);
  --geist-selection: hsla(212, 100%, 92%, 1);

  color-scheme: light;
}

.dark {
  /* Dark Mode */
  --geist-background: #000000;
  --geist-foreground: #ffffff;

  /* Gray Scale */
  --ds-gray-100: hsla(0, 0%, 7%, 1);   /* #121212 - Surface offset */
  --ds-gray-200: hsla(0, 0%, 12%, 1);  /* #1e1e1e */
  --ds-gray-400: hsla(0, 0%, 18%, 1);  /* #2e2e2e - Crisp 1px border */
  --ds-gray-500: hsla(0, 0%, 30%, 1);  /* #4d4d4d */
  --ds-gray-900: hsla(0, 0%, 63%, 1);  /* #a1a1a1 - Secondary text */
  --ds-gray-1000: hsla(0, 0%, 93%, 1); /* #ededed */

  /* Primary Accent & Interactive */
  --ds-blue-700: hsla(212, 100%, 48%, 1); /* #0070f3 */
  --ds-blue-900: hsla(210, 100%, 66%, 1); /* Hover state */

  /* Semantic UI */
  --geist-success: #0070f3;
  --geist-error: #ee0000;
  --geist-warning: #f5a623;

  /* Focus & Selection */
  --ds-focus-color: var(--ds-blue-900);
  --geist-selection: hsla(210, 100%, 25%, 1);

  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  color: var(--geist-foreground);
  background-color: var(--geist-background);
  font-family: var(--font-satoshi), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  overflow-x: hidden;
  transition: background-color 150ms ease, color 150ms ease;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

::selection {
  background-color: var(--geist-selection);
  color: var(--geist-foreground);
}

/* Custom Minimalist Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--geist-background);
}
::-webkit-scrollbar-thumb {
  background: var(--ds-gray-400);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--ds-gray-500);
}

/* Better typography & tabular numbers */
.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* Heading styles with Outfit */
h1, h2, h3, h4, h5, h6, .font-heading {
  font-family: var(--font-outfit), sans-serif;
  letter-spacing: -0.02em;
}

"use client";

import React, { createContext, useContext, useEffect, useState } from "react";

type Theme = "light" | "dark" | "system";

interface ThemeContextType {
  theme: Theme;
  resolvedTheme: "light" | "dark";
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: "dark",
  resolvedTheme: "dark",
  setTheme: () => {},
  toggleTheme: () => {},
});

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme>("dark");
  const [resolvedTheme, setResolvedTheme] = useState<"light" | "dark">("dark");
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    const stored = (localStorage.getItem("theme") as Theme) || "dark";
    setThemeState(stored);
    applyTheme(stored);

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = () => {
      if (localStorage.getItem("theme") === "system") {
        applyTheme("system");
      }
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const applyTheme = (t: Theme) => {
    const root = document.documentElement;
    let effective: "light" | "dark" = "dark";
    if (t === "system") {
      effective = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    } else {
      effective = t;
    }
    setResolvedTheme(effective);
    if (effective === "dark") {
      root.classList.add("dark");
      root.classList.remove("light");
    } else {
      root.classList.remove("dark");
      root.classList.add("light");
    }
  };

  const setTheme = (newTheme: Theme) => {
    setThemeState(newTheme);
    localStorage.setItem("theme", newTheme);
    applyTheme(newTheme);
  };

  const toggleTheme = () => {
    const next = resolvedTheme === "dark" ? "light" : "dark";
    setTheme(next);
  };

  return (
    <ThemeContext.Provider value={{ theme, resolvedTheme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}

