                    ? `${user.proDaysRemaining ?? 30}d`
                    : `${user.runsRemaining} left`}
                  )
                </span>
              </div>
            )}

            <Button
              variant="outline"
              size="icon"
              onClick={signOut}
              title="Sign Out"
              aria-label="Sign Out"
