                  </span>
                ),
              },
            ]}
          />
        </div>

        {/* Tab 1: Curated Daily Opportunities */}
        {activeTab === "opportunities" && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="font-outfit text-lg font-bold text-[var(--geist-foreground)]">
