  /* Glider Blueprint Glassmorphism-Lite & Borders */
  --brand-border: rgba(0, 112, 243, 0.2);
  --brand-border-subtle: rgba(255, 255, 255, 0.08);
  --brand-glass: rgba(0, 0, 0, 0.82);
  --brand-card-bg: rgba(14, 14, 16, 0.7);

  color-scheme: dark;
}

