export interface SwitchProps {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
  className?: string;
  id?: string;
  activeColor?: "blue" | "emerald";
}

export function Switch({
  checked,
  onCheckedChange,
  disabled = false,
  className,
  id,
  activeColor = "blue",
}: SwitchProps) {
  const activeBg =
    activeColor === "emerald"
      ? "bg-emerald-500"
      : "bg-[var(--ds-blue-700)]";

  return (
    <button
      id={id}
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onClick={() => onCheckedChange(!checked)}
      className={cn(
        "relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full border border-transparent transition-colors duration-200 ease-in-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ds-focus-color)] disabled:cursor-not-allowed disabled:opacity-50",
        checked ? activeBg : "bg-[var(--ds-gray-400)]",
        className
      )}
    >
      <span
        aria-hidden="true"
        className={cn(
          "pointer-events-none inline-block size-4 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out",
          checked ? "translate-x-4" : "translate-x-0"
        )}
      />
    </button>
  );
}

